#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ItemType {
    Sword,
    Amulet,
    Staff,
    Potion,
    Rune,
    Moonstone,
}

#[derive(Clone, Copy, Debug)]
pub struct Item {
    pub item_type: ItemType,
}

impl Item {
    pub fn new(item_type: ItemType) -> Self {
        Self { item_type }
    }
}

const PROCESSING_FEE: u64 = 5;

/// Every component is insured at the same uniform rate, whatever its type.
const COMPONENT_BASE_PREMIUM: u64 = 25;

fn base_premium(item_type: ItemType) -> u64 {
    match item_type {
        ItemType::Sword => 100,
        ItemType::Amulet => 60,
        ItemType::Staff => 80,
        ItemType::Potion => 40,
        ItemType::Rune | ItemType::Moonstone => COMPONENT_BASE_PREMIUM,
    }
}

fn policy_base_premium(items: &[Item]) -> u64 {
    items.iter().map(|item| base_premium(item.item_type)).sum()
}

pub fn quote(items: &[Item]) -> u64 {
    policy_base_premium(items) + PROCESSING_FEE
}

#[cfg(test)]

