/// The hazards MHPCO levies on a single item. An item that is both cursed and
/// highly enchanted carries both surcharges; they stack rather than compete.
fn item_risk_surcharge(item: &Item) -> u64 {
    curse_surcharge(item) + high_enchantment_surcharge(item)
}

fn item_risk_surcharges(items: &[Item]) -> u64 {
    items.iter().map(item_risk_surcharge).sum()
}

/// From this many years of business on, a customer counts as long-standing.
const LOYALTY_YEARS: u32 = 2;

/// A long-standing customer receives this share of the policy base premium
/// as a discount.
const LOYALTY_DISCOUNT_RATE: u64 = 20;

fn loyalty_discount(customer: &Customer, policy_base_premium: u64) -> u64 {
    if customer.years_with_mhpco >= LOYALTY_YEARS {
        return percentage_of(policy_base_premium, LOYALTY_DISCOUNT_RATE);
    }
    0
}

/// The modifiers MHPCO levies on the policy as a whole rather than on any one
/// item: they are measured against the policy base premium and turn on the
/// customer's history, not on what is insured. Surcharges count positive and
/// discounts negative, so the catalogue nets out to a single adjustment.
fn policy_wide_modifiers(customer: &Customer, policy_base_premium: u64) -> i64 {
    -(loyalty_discount(customer, policy_base_premium) as i64)
}

pub fn quote(customer: &Customer, items: &[Item]) -> u64 {
    let policy_base_premium = policy_base_premium(items);
    let premium = policy_base_premium + item_risk_surcharges(items);
    let premium = premium.saturating_add_signed(policy_wide_modifiers(customer, policy_base_premium));
    premium + PROCESSING_FEE
}

#[cfg(test)]

