        Self::Moonstone,
    ];
    fn enter_policy_in_the_register(&mut self, items: &[Item]) -> PolicyRef {
        self.policies.push(items.to_vec());
        PolicyRef(self.policies.len() - 1)
    }
    pub fn claim(&mut self, policy: PolicyRef, damages: &[Damage]) -> Option<Settlement> {
        let insured = &self.policies[policy.0];
        let payout: Hundredths = damages
            .iter()
            .map(|damage| {
                let item = insured_item_for(insured, damage);
                damage_reimbursement(item, damage.amount)
            })
            .sum();
        Some(Settlement {
            payout: payout.rounded_down_to_whole_g(),
            remaining_cap: 0,
        })
    }

